// Demonstrating virtual memory's lazy allocation in Node.js
// Physical pages are only mapped when first accessed (demand paging)
const v8 = require('v8');

const PAGE_SIZE = 4096; // 4 KB — the standard OS page size
const SIZE = 256 * 1024 * 1024; // 256 MB virtual reservation

// Buffer.allocUnsafe reserves virtual address space immediately.
// The OS does NOT allocate physical RAM yet — it only records the
// reservation in the page table with Present bit = 0.
const buf = Buffer.allocUnsafe(SIZE);

const before = process.memoryUsage();
console.log('Virtual size:  ', (before.heapTotal / 1e6).toFixed(1), 'MB');
console.log('RSS before touch:', (before.rss / 1e6).toFixed(1), 'MB');
// RSS (Resident Set Size) = physical pages currently mapped into this process

// Now touch one byte per page — each first access triggers a minor page fault.
// The OS allocates a physical frame and maps it into the page table.
// You can observe RSS growing proportionally to the pages you touch.
for (let i = 0; i < SIZE; i += PAGE_SIZE) {
  buf[i] = 0xff;
}

const after = process.memoryUsage();
console.log('RSS after touch:', (after.rss / 1e6).toFixed(1), 'MB');
// RSS has grown by ~256 MB — every page is now physically mapped

// Address translation formula (conceptual)
function conceptualTranslate(virtualAddr, pageTable, pageSize) {
  const pageNumber = Math.floor(virtualAddr / pageSize);  // upper bits
  const offset     = virtualAddr % pageSize;              // lower bits
  const frameNumber = pageTable[pageNumber];
  if (frameNumber === undefined) throw new Error('Page fault!');
  return frameNumber * pageSize + offset; // physical address
}

// Example: virtual address 0x5FFF with PAGE_SIZE=4096
// page number = 0x5FFF >> 12 = 5
// offset      = 0x5FFF & 0xFFF = 0xFFF = 4095
console.log(conceptualTranslate(0x5FFF, { 5: 100 }, PAGE_SIZE));
// → 100 * 4096 + 4095 = 413695 (physical byte 413695)

// Virtual address space layout (conceptual — Linux x86-64)
// Regions from low to high addresses:

const virtualAddressSpace = {
  nullPage:      { range: '0x0000000000000000',          note: 'unmapped — null ptr dereference faults here' },
  text:          { range: '0x0000000000400000',          note: 'read-only executable code (.text, .rodata)' },
  data:          { range: '0x0000000000600000',          note: 'initialized globals (.data)' },
  bss:           { range: '0x0000000000601000',          note: 'zero-filled uninitialized globals (.bss)' },
  heap:          { range: '0x0000000000602000  ↑ grows up',  note: 'malloc / new — expands via brk/mmap' },
  mmapRegion:    { range: '0x00007f0000000000 ↕',        note: 'shared libs, file mmap, anonymous mmap' },
  stack:         { range: '0x00007fffffffffff ↓ grows down', note: 'thread stack — default 8 MB limit' },
  kernelSpace:   { range: '0xffff800000000000 and up',   note: 'kernel — supervisor only, never user-accessible' },
};

// Address split for 4-level paging (48-bit virtual address)
// Bits: [63..48]=sign extend  [47..39]=PGD  [38..30]=PUD  [29..21]=PMD  [20..12]=PT  [11..0]=offset
function splitVirtualAddress(va) {
  return {
    pgdIndex: (va >> 39n) & 0x1FFn,   // bits 47-39 (9 bits)
    pudIndex: (va >> 30n) & 0x1FFn,   // bits 38-30 (9 bits)
    pmdIndex: (va >> 21n) & 0x1FFn,   // bits 29-21 (9 bits)
    ptIndex:  (va >> 12n) & 0x1FFn,   // bits 20-12 (9 bits)
    offset:   va & 0xFFFn,            // bits 11-0  (12 bits)
  };
}

// Example: dissect virtual address 0x00007fff5fbf1234n
const result = splitVirtualAddress(0x00007fff5fbf1234n);
console.log(result);
// pgdIndex: 0n (PGD entry 0)
// pudIndex: 255n
// pmdIndex: 509n
// ptIndex:  497n
// offset:   0x234n = 564 bytes into the page
